commit a4d6d4656f6e14cda68cbb37539584d058231d5d
Author:     John Bieling <john@thunderbird.net>
AuthorDate: Sun Nov 23 12:26:47 2025 +0200
Commit:     John Bieling <john@thunderbird.net>
CommitDate: Sun Nov 23 12:26:47 2025 +0200

    Bug 1903727 - Enable support for proxy API. r=mkmelin


    In the past, the proxy API failed with error messages about missing preferences,
    which can no longer be observed. This patch enables official support for the
    proxy API in the documentation.

    Differential Revision: https://phabricator.services.mozilla.com/D272231

diff --git a/mail/components/extensions/annotations/proxy.json b/mail/components/extensions/annotations/proxy.json
new file mode 100644
index 00000000000..d531db08535
--- /dev/null
+++ b/mail/components/extensions/annotations/proxy.json
@@ -0,0 +1,45 @@
+[
+  {
+    "namespace": "manifest",
+    "types": [
+      {
+        "$extend": "OptionalPermission",
+        "choices": [
+          {
+            "type": "string",
+            "enums": {
+              "proxy": {
+                "annotations": [
+                  {
+                    "version_added": "147"
+                  }
+                ]
+              }
+            }
+          }
+        ]
+      }
+    ]
+  },
+  {
+    "namespace": "proxy",
+    "annotations": [
+      {
+        "version_added": "147"
+      }
+    ],
+    "properties": {
+      "settings": {
+        "annotations": [
+          {
+            "version_added": "false"
+          },
+          {
+            "note": "Not supported in Thunderbird because it depends on private browsing functionality, which Thunderbird does not fully implement.",
+            "bcd": true
+          }
+        ]
+      }
+    }
+  }
+]
